const body = $input.first().json.body || $input.first().json;

const itemId = body.item_id;
const quantity = Number(body.quantity);
const transactionType = body.transaction_type;
const projectId = body.project_id;
const performedBy = body.performed_by;

// Validate required fields
if (!itemId || quantity === undefined || !transactionType || !projectId || !performedBy) {
  throw new Error(`Missing required fields. Received: ${JSON.stringify(body)}`);
}

// Validate transaction type
const validTypes = ['entrada', 'saida', 'ajuste', 'transferencia'];
if (!validTypes.includes(transactionType)) {
  throw new Error(`Invalid transaction_type: '${transactionType}'. Must be one of: ${validTypes.join(', ')}`);
}

// Validate quantity
if (isNaN(quantity) || quantity <= 0) {
  throw new Error(`Invalid quantity: ${quantity}. Must be a positive number.`);
}

const stockDelta = (transactionType === 'saida') ? -quantity : quantity;

return [{
  json: {
    item_id: itemId,
    quantity: quantity,
    stock_delta: stockDelta,
    transaction_type: transactionType,
    project_id: projectId,
    performed_by: performedBy,
    timestamp: new Date().toISOString()
  }
}];

const scanData = $('Validate & Parse Input').first().json;
const itemData = $input.first().json;

if (!itemData || !Array.isArray(itemData) || itemData.length === 0) {
  throw new Error(`Item not found in Supabase: ${scanData.item_id}`);
}

const item = itemData[0];
const currentStock = Number(item.current_stock);
const newStock = currentStock + scanData.stock_delta;

if (newStock < 0) {
  throw new Error(`Insufficient stock. Current: ${currentStock}, Requested: ${scanData.quantity}`);
}

const isLowStock = newStock <= Number(item.minimum_stock);

return [{
  json: {
    // Scan data
    item_id: scanData.item_id,
    quantity: scanData.quantity,
    stock_delta: scanData.stock_delta,
    transaction_type: scanData.transaction_type,
    project_id: scanData.project_id,
    performed_by: scanData.performed_by,
    timestamp: scanData.timestamp,

    // Item data
    item_name: item.name,
    previous_stock: currentStock,
    new_stock: newStock,
    minimum_stock: Number(item.minimum_stock),
    unit: item.unit,
    supplier_id: item.supplier_id,
    warehouse_location: item.warehouse_location,

    // Alert flag
    is_low_stock: isLowStock
  }
}];
